parameters.jsCode:
const texto = ($json.output || '').toString();
const limpio = texto.replace(/```json|```/g, '').trim();
let datos;
let falla = false;
try {
  datos = JSON.parse(limpio);
  if (typeof datos.respuesta !== 'string' || datos.respuesta.trim() === '' || typeof datos.derivar !== 'boolean') {
    throw new Error('Formato incompleto');
  }
} catch (e) {
  falla = true;
  datos = {
    respuesta: 'Disculpá, tuve un problema para procesar tu mensaje. Una persona del equipo te va a escribir por este chat.',
    derivar: true,
    motivo: 'Falla de formato: el agente devolvió una respuesta vacía o inválida',
    fuente: '',
    registro: null
  };
}
datos.falla = falla;
return { json: datos };
